CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"f7752d6f-85e2-55ed-8a33-a8ad479709dc","source_id":"0975","name_en":"band close-grip push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629","match_names":["band close-grip push-up"],"muscle":"triceps","equipment":"band","aliases":["band close-grip push-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Place a band around your upper arms, just above the elbows.\nAssume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.\nBend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.\nPush through your palms to extend your arms and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0631\u0628\u0627\u0637\u064b\u0627 \u062d\u0648\u0644 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643\u060c \u0641\u0648\u0642 \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0627\u062a\u062e\u0630 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0975","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0975-ufaxB52.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0975-ufaxB52.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0576a838-013b-50e2-8536-47b57a67b429","source_id":"0976","name_en":"band concentration curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band concentration curl"],"muscle":"biceps","equipment":"band","aliases":["band concentration curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench or chair with your legs spread apart and your feet flat on the ground.\nHold one end of the band in your hand and step on the other end with your foot on the same side.\nLean forward slightly and rest your elbow on the inside of your thigh, just above the knee.\nWith your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.\nPause for a moment at the top, then slowly lower your hand back down to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0633\u0627\u0642\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0623\u062d\u062f \u0637\u0631\u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u064a\u062f\u0643 \u0648\u062e\u0637\u0648 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u0641 \u0627\u0644\u0622\u062e\u0631 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u0643 \u0639\u0644\u0649 \u0646\u0641\u0633 \u0627\u0644\u062c\u0627\u0646\u0628.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0636\u0639\u064a \u0645\u0631\u0641\u0642\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0641\u062e\u0630\u0643\u060c \u0641\u0648\u0642 \u0627\u0644\u0631\u0643\u0628\u0629 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0642\u0645 \u0628\u0644\u0641 \u064a\u062f\u0643 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u064a\u062f\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0976","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0976-kmVVAfu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0976-kmVVAfu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f4c94a55-6318-5a62-8f90-4f8b84bdc267","source_id":"3117","name_en":"band fixed back close grip pulldown","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u062b\u0627\u0628\u062a\u0629 \u0627\u0644\u0638\u0647\u0631 \u0642\u0628\u0636\u0629 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629","match_names":["band fixed back close grip pulldown"],"muscle":"back","equipment":"band","aliases":["band fixed back close grip pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.\nSit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.\nGrasp the band with a close grip, palms facing towards you.\nKeep your back straight and engage your core.\nPull the band down towards your chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, feeling the contraction in your lats.\nSlowly release the band back to the starting position, maintaining control throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0646\u0642\u0637\u0629 \u062b\u0627\u0628\u062a\u0629 \u0641\u0648\u0642\u0643\u060c \u0645\u062b\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0623\u0648 \u0627\u0644\u0639\u0627\u0631\u0636\u0629 \u0627\u0644\u0642\u0648\u064a\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0643\u0645\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634 \u0641\u064a \u0639\u0636\u0644\u0627\u062a\u0643.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3117","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3117-4LoWllp.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3117-4LoWllp.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1a5abbab-0a19-591f-86bd-888d767dd365","source_id":"3116","name_en":"band fixed back underhand pulldown","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u062b\u0627\u0628\u062a\u0629 \u0627\u0644\u0638\u0647\u0631 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629","match_names":["band fixed back underhand pulldown"],"muscle":"back","equipment":"band","aliases":["band fixed back underhand pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a sturdy anchor point above your head.\nStand facing the anchor point with your feet shoulder-width apart.\nGrasp the band with an underhand grip, hands slightly wider than shoulder-width apart.\nStep back to create tension in the band, keeping your arms fully extended.\nEngage your core and squeeze your shoulder blades together.\nPull the band down towards your chest, leading with your elbows.\nPause for a moment at the bottom of the movement, feeling the contraction in your lats.\nSlowly release the tension in the band and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0646\u0642\u0637\u0629 \u062a\u062b\u0628\u064a\u062a \u0642\u0648\u064a\u0629 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0639\u062f \u0644\u0644\u062e\u0644\u0641 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634 \u0641\u064a \u0639\u0636\u0644\u0627\u062a\u0643.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3116","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3116-ZH68exZ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-datas