\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0977","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0977-sTg7iys.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0977-sTg7iys.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ad1239ad-d275-5d54-84cf-30152183d531","source_id":"0978","name_en":"band front raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629","match_names":["band front raise"],"muscle":"shoulders","equipment":"band","aliases":["band front raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.\nKeep your arms straight and slowly raise them forward until they are parallel to the ground.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0627\u0631\u0641\u0639\u0647\u0645\u0627 \u0628\u0628\u0637\u0621 \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0978","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0978-TFA88iB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0978-TFA88iB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2a529da3-6af7-599f-8eb6-874f9f73ce1d","source_id":"1408","name_en":"band hip lift","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band hip lift"],"muscle":"glutes","equipment":"band","aliases":["band hip lift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie on your back with your knees bent and feet flat on the ground.\nPlace a resistance band just above your knees.\nEngage your glutes and core muscles.\nPress your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u0634\u0631\u064a\u0637 \u0645\u0642\u0627\u0648\u0645\u0629 \u0641\u0648\u0642 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629.\n\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u0648\u0627\u0644\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1408","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1408-E4R8Hz1.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1408-E4R8Hz1.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8d0beb7c-74a6-5b9f-87b3-407adb6b74a1","source_id":"0979","name_en":"band horizontal pallof press","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u0623\u0641\u0642\u064a\u0629 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0628\u0627\u0644\u0648\u0641","match_names":["band horizontal pallof press"],"muscle":"core","equipment":"band","aliases":["band horizontal pallof press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a sturdy anchor point at waist height.\nStand perpendicular to the anchor point with your feet shoulder-width apart.\nGrasp the band handle with both hands and step away from the anchor point to create tension in the band.\nBring your hands to your chest, keeping your elbows bent and close to your body.\nEngage your core and maintain a stable stance.\nExtend your arms straight out in front of you, pushing the band away from your body.\nHold the extended position for a few seconds, focusing on maintaining tension in your core.\nSlowly bring your hands back to your chest, resisting the pull of the band.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0646\u0642\u0637\u0629 \u062a\u062b\u0628\u064a\u062a \u0642\u0648\u064a\u0629 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u062e\u0635\u0631.\n\u0642\u0641 \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0627\u0628\u062a\u0639\u062f \u0639\u0646 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062b\u0646\u064a\u064a\u0646 \u0648\u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u062e\u0