39\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0627\u0631\u0641\u0639\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0993","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["upper back","trapezius"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0993-sTfvVsG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0993-sTfvVsG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e16f6fc1-c38e-5405-8bd1-52969bf1e1ee","source_id":"0994","name_en":"band reverse wrist curl","name_ar":"\u0634\u0631\u064a\u0637 \u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0645\u0639\u0635\u0645 \u0627\u0644\u0639\u0643\u0633\u064a","match_names":["band reverse wrist curl"],"muscle":"forearms","equipment":"band","aliases":["band reverse wrist curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench or chair with your feet flat on the ground.\nHold the band with an overhand grip, palms facing down, and wrap it around your fingers.\nRest your forearms on your thighs, with your wrists hanging off the edge.\nSlowly curl your wrists upward, squeezing your forearms.\nPause for a moment at the top, then slowly lower your wrists back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0648\u0644\u0641\u0647 \u062d\u0648\u0644 \u0623\u0635\u0627\u0628\u0639\u0643.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0645\u0639\u0635\u0645\u064a\u0643 \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0994","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0994-Ezpnw9d.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0994-Ezpnw9d.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6e9fe6fb-fd37-503f-83e3-1c8553383d8b","source_id":"0996","name_en":"band seated hip internal rotation","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u064a\u062c\u0644\u0633 \u062f\u0648\u0631\u0627\u0646 \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u062f\u0627\u062e\u0644\u064a","match_names":["band seated hip internal rotation"],"muscle":"glutes","equipment":"band","aliases":["band seated hip internal rotation"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a chair or bench with your back straight and feet flat on the ground.\nPlace a resistance band around your thighs, just above your knees.\nKeep your knees bent at a 90-degree angle and your feet shoulder-width apart.\nEngage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.\nPause for a moment at the end of the movement, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0623\u0648 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u0634\u0631\u064a\u0637 \u0645\u0642\u0627\u0648\u0645\u0629 \u062d\u0648\u0644 \u0641\u062e\u0630\u064a\u0643\u060c \u0641\u0648\u0642 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0627\u062a \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0996","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0996-9gbyYKk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0996-9gbyYKk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b0bef450-b288-53c8-8145-536c0acd667b","source_id":"1011","name_en":"band seated twist","name_ar":"\u062a\u0637\u0648\u0631 \u0627\u0644\u0641\u0631\u0642\u0629 \u062c\u0627\u0644\u0633\u0627","match_names":["band seated twist"],"muscle":"core","equipment":"band","aliases":["band seated twist"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you and your back straight.\nWrap the band around your waist and hold the ends with both hands.\nEngage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.\nPause for a moment at the end of the twist, then slowly return to the starting position.\nRepeat the twist to the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b.\n\u0644\u0641 \u0627\u0644\u0634\u0631\u064a\u0637 \u062d\u0648\u0644 \u062e\u0635\u0631\u0643 \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u0623\u0637\u0631\u0627\u0641 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643.\n\u0627\u0634\u063a\u0644 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0644\u0641 \u062c\u0630\u0639\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0627\u0644\u062a\u0648\u0627\u0621\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u062a\u0637\u0648\u0631 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1011","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"ma