0627 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631.\n\u0627\u0631\u0641\u0639 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0631\u0641\u0639 \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u064a\u0645\u0646\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0999","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["ankles","feet"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0999-9JprnPh.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0999-9JprnPh.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4253a04c-99f4-5011-886e-dc338fd30fa9","source_id":"1000","name_en":"band single leg reverse calf raise","name_ar":"\u0631\u0641\u0639 \u0631\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0642 \u0628\u0634\u0643\u0644 \u0639\u0643\u0633\u064a \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["band single leg reverse calf raise"],"muscle":"calves","equipment":"band","aliases":["band single leg reverse calf raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet hip-width apart and place the band around the ball of your foot.\nHold onto a stable object for balance.\nSlowly raise your heel off the ground, lifting your body weight onto the ball of your foot.\nPause for a moment at the top, then slowly lower your heel back down to the starting position.\nRepeat for the desired number of repetitions, then switch to the other leg.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643 \u062b\u0645 \u0636\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u062d\u0648\u0644 \u0643\u0631\u0629 \u0642\u062f\u0645\u0643.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u062c\u0633\u0645 \u0645\u0633\u062a\u0642\u0631 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0627\u0631\u0641\u0639 \u0643\u0639\u0628\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0631\u0641\u0639 \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1000","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1000-QsSQWbf.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1000-QsSQWbf.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6fa8c74f-1e39-58d2-8a52-817c182a45d2","source_id":"1001","name_en":"band single leg split squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0645\u0642\u0633\u0645 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["band single leg split squat"],"muscle":"quads","equipment":"band","aliases":["band single leg split squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet hip-width apart and place a resistance band around your ankles.\nTake a big step forward with your right foot and a smaller step back with your left foot.\nBend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.\nPush through your right heel to return to the starting position.\nRepeat on the other side.","steps_ar"