ndles with your palms facing each other and your arms extended in front of you.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nPull the band towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly release the tension and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u062b\u0645 \u0636\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u062a\u062d\u062a \u0642\u062f\u0645\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1022","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1022-tc5dYrf.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1022-tc5dYrf.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c59f1f82-8afc-51b8-8812-60ea54b56596","source_id":"1007","name_en":"band standing twisting crunch","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u062f\u0627\u0626\u0645\u0629 \u0623\u0632\u0645\u0629 \u0627\u0644\u062a\u0648\u0627\u0621","match_names":["band standing twisting crunch"],"muscle":"core","equipment":"band","aliases":["band standing twisting crunch"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.\nHold the ends of the band with your hands, keeping your elbows bent and close to your sides.\nEngage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.\nPause for a moment, then return to the starting position.\nRepeat on the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u062b\u0645 \u0636\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u062d\u0648\u0644 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643\u060c \u0648\u0627\u0639\u0628\u0631\u0647 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643.\n\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062b\u0646\u064a\u064a\u0646 \u0648\u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u062c\u0644\u0628 \u0645\u0631\u0641\u0642\u0643 \u0646\u062d\u0648 \u0627\u0644\u0631\u0643\u0628\u0629 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1007","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1007-euq4pwp.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1007-euq4pwp.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"75e99215-7f03-5dc2-8489-c5449a74a03a","source_id":"1008","name_en":"band step-up","name_ar":"\u062a\u0635\u0639\u064a\u062f \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band step-up"],"muscle":"glutes","equipment":"band","aliases":["band step-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Place a band around your thighs, just above your knees.\nStand facing a step or platform with your feet hip-width apart.\nStep up onto the platform with your right foot, pushing through your heel.\nExtend your left leg behind you, keeping it straight.\nLower your left foot back down to the ground.\nRepeat with your left foot stepping up onto the platform.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0631\u0628\u0627\u0637\u064b\u0627 \u062d\u0648\u0644 \u0641\u062e\u0630\u064a\u0643\u060c \u0641\u0648\u0642 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062e\u0637\u0648\u0629 \u0623\u0648 \u0645\u0646\u0635\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0627\u0635\u0639\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u0643.\n\u0645\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u062e\u0644\u0641\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u062e\u0641\u0636 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0635\u0639\u0648\u062f \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1008","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1008-d5bTEPV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1008-d5bTEPV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9c68846b-0991-51ad-8e69-d3721b283251","source_id":"1009","name_en":"band stiff leg deadlift","name_ar":"\u0627\u0644\u0631\u0641\u0639\u0629 \u0627\u0644\u0645\u0645\u064a\u062a\u0629 \u0644\u0644\u0633\u0627\u0642 \u0627\u0644\u0642\u0627\u0633\u064a\u0629","match_names":["band stiff leg deadlift"],"muscle":"glutes","equipment":"band","aliases":["band stiff leg deadlift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and place the band around your ankles.\nHold the band with both hands in front of your thighs, palms facing your body.\nKeeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.\nAs you lower, push your hips back and allow your knees to bend slightly.\nLower the band towards the ground, feeling a stretch in your hamstrings.\nPause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u062b\u0645 \u0636\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u062d\u0648\u0644 \u0643\u0627\u062d\u0644\u064a\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643\u060c \u0648\u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f \u0645\u0648\u0627\u062c\u0647\u062a\u0627\u0646 \u0644\u062c\u0633\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630