attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6e289f2e-7563-5d4b-8763-fa79c9da49e9","source_id":"1014","name_en":"band v-up","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0639\u0644\u0649 \u0634\u0643\u0644 \u062d\u0631\u0641 V","match_names":["band v-up"],"muscle":"core","equipment":"band","aliases":["band v-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on your back with your legs straight and your arms extended overhead, holding the band.\nEngaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.\nPause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u0641\u0631\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062f\u0648\u062f\u062a\u064a\u0646 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0645\u0633\u0643\u064a\u0646 \u0628\u0627\u0644\u0634\u0631\u064a\u0637.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a\u060c \u0648\u062a\u0635\u0644 \u0628\u064a\u062f\u064a\u0643 \u0646\u062d\u0648 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1014","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1014-H6ETwO9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1014-H6ETwO9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"be1ccb44-be12-572f-87cd-08527cca2b5d","source_id":"1015","name_en":"band vertical pallof press","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u0639\u0645\u0648\u062f\u064a\u0629 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0628\u0627\u0644\u0648\u0641","match_names":["band vertical pallof press"],"muscle":"core","equipment":"band","aliases":["band vertical pallof press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.\nHold the band with both hands and step away from the anchor point, creating tension in the band.\nPosition yourself perpendicular to the anchor point, with your side facing the band.\nExtend your arms straight out in front of you, keeping your hands at chest height.\nEngage your core and press the band away from your chest, fully extending your arms.\nHold the position for a few seconds, then slowly bring the band back towards your chest.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0644\u0641 \u0627\u0644\u0634\u0631\u064a\u0637 \u062d\u0648\u0644 \u062c\u0633\u0645 \u0642\u0648\u064a \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0627\u0628\u062a\u0639\u062f \u0639\u0646 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a\u060c \u0645\u0645\u0627 \u064a\u062e\u0644\u0642 \u062a\u0648\u062a\u0631\u064b\u0627 \u0641\u064a \u0627\u0644\u062d\u0632\u0627\u0645.\n\u0636\u0639 \u0646\u0641\u0633\u0643 \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u0646\u0642\u0637\u0629 \u0627\u0644\u0631\u0628\u0637\u060c \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u062c\u0627\u0646\u0628\u0643 \u0645\u0648\u0627\u062c\u0647\u064b\u0627 \u0644\u0644\u0634\u0631\u064a\u0637.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0635\u062f\u0631\u0643\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1015","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1015-G7PXMlT.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1015-G7PXMlT.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"606d6d43-0bd2-5fe4-8bd7-7da5ffad67bb","source_id":"1016","name_en":"band wrist curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0639\u0635\u0645 \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band wrist curl"],"muscle":"forearms","equipment":"band","aliases":["band wrist curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench or chair with your feet flat on the ground.\nHold the band with both hands, palms facing up, and rest your forearms on your thighs.\nSlowly curl your wrists upward, squeezing your forearms.\nPause for a moment at the top, then slowly lower your wrists back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1016","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_tar